    "Website SEO data (free: Open PageRank)": "ウェブサイトのSEOデータ（無料：Open PageRank）",
    "Free: get a key at openpagerank.keywordseverywhere.com/dashboard (sign in with a Keywords Everywhere key; old DomCop keys no longer work). It gives a 0-10 authority score and the world rank of a lead website. Used when no Ahrefs or Ubersuggest key answers. The basic SEO checks (title, description, mobile, indexing, robots.txt, sitemap) need no key at all.": "無料：openpagerank.keywordseverywhere.com/dashboard でキーを取得します（アカウントだけで可）。リードのサイトの0〜10の権威スコアと世界ランクが分かります。AhrefsやUbersuggestのキーが応答しないときに使われます。基本のSEOチェック（タイトル、説明、モバイル、インデックス、robots.txt、サイトマップ）はキー不要です。",
    "Open PageRank API key": "Open PageRank APIキー",
    "World rank": "世界ランク",
    "SEO basics": "SEOの基本",
    "SEO figures (authority, traffic, keywords, backlinks) appear here once an Ahrefs, Ubersuggest or free Open PageRank key is saved in Settings → AI.": "Ahrefs、Ubersuggest、または無料のOpen PageRankのキーを設定 → AI に保存すると、SEOの数値（権威性、トラフィック、キーワード、被リンク）がここに表示されます。",
    "Website SEO data (Ahrefs)": "ウェブサイトのSEOデータ (Ahrefs)",
    "With your Ahrefs API key (API v3), hovering the website of a lead shows its domain rating, organic traffic and keywords, and backlinks. When both keys are saved, Ahrefs is used. The key is stored encrypted and never shown again.": "Ahrefs APIキー（API v3）を設定すると、リードのウェブサイトにカーソルを合わせたときにドメインレーティング、オーガニックトラフィックとキーワード、被リンクが表示されます。両方のキーがある場合はAhrefsが使われます。キーは暗号化して保存され、再表示されません。",
    "Ahrefs API key": "Ahrefs APIキー",
