    "Create a bot with @BotFather and paste its token. Each person then sends /start to the bot and enters their chat id (for example from @userinfobot) in their profile.": "@BotFatherでボットを作成し、トークンを貼り付けてください。各ユーザーはボットに /start を送信し、プロフィールにチャットID（例：@userinfobot）を入力します。",
