    "Create the missing payroll expenses?": "不足している給与経費を作成しますか?",
    "Every payroll payment that has no expense yet gets one in the Payroll category. Payments that already have one are not touched. Expenses entered by hand are never changed.": "経費のない給与支払いごとに「給与」カテゴリの経費を作成します。すでにあるものは変更しません。手入力の経費は変更されません。",
