    "To restore a file, download it and run: node scripts/restore-backup.mjs <file> (add --apply to write).": "復元するには、ファイルをダウンロードして node scripts/restore-backup.mjs <ファイル> を実行します(書き込みには --apply を追加)。",
    "Your administrator requires two-step sign-in. Turn on the authenticator app or the email code below to keep using the CRM.": "管理者が2段階認証を必須にしています。続けるには、下の認証アプリまたはメールコードを有効にしてください。",
    "Your administrator requires two-step sign-in: turn it on in your profile, Security, to continue.": "管理者が2段階認証を必須にしています。プロフィールのセキュリティで有効にしてください。",
    "Two-step sign-in": "2段階認証",
