    "Administrators and people who see the vault, payments or payroll": "管理者と、保管庫・支払い・給与を見られる人",
    "Make the second step (authenticator app or email code) compulsory. Someone the rule covers who has not turned it on can only open their profile, Security, until they do. Everybody can always turn it on themselves.": "第2段階(認証アプリまたはメールコード)を必須にします。対象者が未設定の間は、プロフィールのセキュリティしか開けません。誰でも自分で有効にできます。",
