    "Back up the database every night": "毎晩データベースをバックアップする",
    "Every night after 02:00 (company time) the whole database is saved to the file storage: the last 14 days and one a week for 12 weeks. It does not need the automatic tasks to be on.": "毎晩02:00(会社時間)以降にデータベース全体がファイルストレージに保存されます。直近14日分と、12週間分は週1回分を保持します。自動タスクがオフでも動作します。",
    "Alerts": "アラート",
    "Send alerts to the administrators": "管理者にアラートを送る",
    "The administrators are told (bell, email, Telegram / WhatsApp) when a backup fails or is late, when the automatic tasks stop or report errors, and when the CRM returns a burst of server errors. The same alert is sent once an hour at most.": "バックアップの失敗・遅延、自動タスクの停止やエラー、サーバーエラーの多発時に、管理者へ通知します(ベル、メール、Telegram / WhatsApp)。同じアラートは1時間に1回までです。",
