    "Check the WhatsApp connection": "WhatsApp接続を確認",
    "Connected": "接続済み",
    "It will stop working then: paste a permanent token, or add the App ID and App Secret above.": "その時点で動作しなくなります。永続トークンを貼り付けるか、上でApp IDとApp Secretを追加してください。",
    "Renew the token now": "今すぐトークンを更新",
    "The token does not expire": "トークンに有効期限はありません",
    "The token ends on": "トークンの有効期限",
    "The token was renewed": "トークンを更新しました",
    "quality": "品質",
    "App ID (optional)": "App ID(任意)",
    "App Secret (optional)": "App Secret(任意)",
    "Meta for Developers → your app → App settings → Basic. Not needed to send. With the App Secret it lets the CRM check the token and renew it (a 24-hour test token becomes a 60-day one).": "Meta for Developers → アプリ → 設定 → ベーシック。送信には不要です。App Secretがあれば、CRMがトークンを確認・更新できます(24時間のテストトークンが60日になります)。",
    "Views by the team": "チームによる閲覧",
    "Do not count the team opening the public pages": "チームが公開ページを開いたときはカウントしない",
    "When a team member opens the public page of an invoice, estimate, proposal or contract (signed in, or from an address a team member used lately, even in a private window), it is not recorded as the client having seen it, so no \"Client opened a proposal\" notification.": "チームメンバーが請求書・見積書・提案書・契約書の公開ページを開いた場合(ログイン中、またはチームが最近使ったアドレスから。プライベートウィンドウでも)、顧客の閲覧としては記録されず、「顧客が提案書を開きました」の通知も出ません。",
    "The WhatsApp access token is not valid or has expired. Create a permanent token (Meta Business Settings → System users → Generate token with the whatsapp_business_messaging permission) and paste it in Settings, or add the App ID and App Secret so the CRM renews it.": "WhatsAppのアクセストークンが無効または期限切れです。永続トークン(Meta Business Settings → システムユーザー → whatsapp_business_messaging権限でトークン生成)を作成して設定に貼り付けるか、App IDとApp Secretを追加してCRMに更新させてください。",
    "This number is not in the list of recipients allowed for the Meta test number. Add it in Meta for Developers → WhatsApp → API setup → \"To\", or switch to a real business number.": "この番号はMetaのテスト番号で許可された受信者リストにありません。Meta for Developers → WhatsApp → API setup →「To」に追加するか、本番の事業用番号に切り替えてください。",
    "WhatsApp only allows a free message within 24 hours of the person writing to you. Set the name of an approved template in Settings (Template name), or ask the person to send you a message first.": "WhatsAppでは、相手からのメッセージ後24時間以内のみ自由なメッセージを送れます。設定で承認済みテンプレート名を指定するか、先に相手からメッセージを送ってもらってください。",
    "WhatsApp does not accept the template: check its name, its language code and that its body has exactly one variable ({{1}}) in Settings.": "WhatsAppがテンプレートを受け付けません。名前、言語コード、本文に変数({{1}})がちょうど1つあることを設定で確認してください。",
    "This number is not on WhatsApp, or it cannot receive the message. Check the number (with the country code).": "この番号はWhatsAppを利用していないか、メッセージを受信できません。番号(国番号付き)を確認してください。",
    "The Phone number ID is not right: copy it again from Meta for Developers → WhatsApp → API setup (it is not the phone number itself).": "電話番号IDが正しくありません。Meta for Developers → WhatsApp → API setupから再度コピーしてください(電話番号そのものではありません)。",
    "WhatsApp is slowing the account down (too many messages too fast). Try again in a few minutes.": "WhatsAppがアカウントを制限しています(短時間に多数送信)。数分後に再試行してください。",
    "The WhatsApp Business account has a payment or account problem: open it in Meta Business Manager.": "WhatsApp Businessアカウントに支払いまたはアカウントの問題があります。Meta Business Managerで確認してください。",
    "WhatsApp refused the message": "WhatsAppがメッセージを拒否しました",
    "The WhatsApp access token needs attention": "WhatsAppアクセストークンの確認が必要です",
    "Approved templates": "承認済みテンプレート",
    "Callback URL": "コールバックURL",
    "Verify token": "検証トークン",
    "Recent messages that were not delivered": "最近配信されなかったメッセージ",
    "Webhook (optional, to learn about failed deliveries)": "Webhook(任意・配信失敗の把握用)",
    "Meta for Developers → WhatsApp → Configuration → Webhook → Edit, then subscribe to “messages”.": "Meta for Developers → WhatsApp → Configuration → Webhook → Edit で「messages」を購読してください。",
    "WhatsApp Business Account ID (optional)": "WhatsApp BusinessアカウントID(任意)",
    "Meta for Developers → WhatsApp → API setup, under the phone number. Lets the CRM list your approved templates and check the one below.": "Meta for Developers → WhatsApp → API setup の電話番号の下にあります。承認済みテンプレートを一覧し、下のテンプレートを確認できます。",
    "WhatsApp does not accept this number. Write it with the country code and nothing else, for example +212 600 000 000 (no 0 in front of the local part).": "WhatsAppはこの番号を受け付けません。国番号付きで、それ以外は入れずに入力してください(例:+212 600 000 000、先頭の0なし)。",
    "Write the number with the country code (for example +212 600 000 000), without the 0 in front.": "国番号付きで入力してください(例:+212 600 000 000)。先頭の0は不要です。",
    "This does not look like a phone number with its country code.": "国番号付きの電話番号には見えません。",
    "A WhatsApp message was not delivered": "WhatsAppメッセージが配信されませんでした",
    "Internal note (the client does not see it)": "社内メモ(顧客には見えません)",
    "Nothing to tell today: no email was sent": "今日お伝えすることはありません。メールは送信されませんでした",
    "One email each morning (new for you, tasks due, reminders and meetings of the day) instead of one email for each event. Chat apps and the bell are not affected.": "イベントごとのメールの代わりに、毎朝1通(新着・期限のタスク・リマインダー・今日の予定)。チャットアプリとベルには影響しません。",
    "One summary a day": "1日1通のまとめ",
