    "Daily summary email at (hour)": "毎日のまとめメールの時刻(時)",
    "For the team members who chose \"One summary a day\" in their profile (Notifications): one email at this hour of the company clock, only when there is something to tell.": "プロフィールの通知で「1日1通のまとめ」を選んだメンバー向け:会社の時計のこの時刻に1通、伝えることがある場合のみ送信されます。",
