    "How to work better as a team: update your tasks, answer tickets fast, write notes": "チームでより良く働く：タスクを更新し、チケットに素早く返信し、メモを書く",
    "A friendly reminder to log your time and close finished tasks every Friday": "毎週金曜日に作業時間を記録し、完了したタスクを閉じるようにというやさしいリマインダー",
    "Congratulate the team on this month's results and thank everybody": "今月の成果をチームに祝福し、全員に感謝する",
    "Booking page: days and hours": "予約ページ：曜日と時間",
    "When visitors can book a meeting on the Meet booking page. Times are in the company time zone (Settings → Localization). A day or month you close here is never offered; single closed days and holidays are managed from the Calendar page.": "訪問者がMeetの予約ページで会議を予約できる時間帯。時間は会社のタイムゾーン（設定→ローカライズ）です。ここで休みにした日や月は表示されません。個別の休業日や祝日はカレンダーページで管理します。",
    "Days people can book": "予約できる曜日",
    "Hours of the day": "時間帯",
    "Hours from-to, separated by commas: 10-13,14-17 = 10:00 to 13:00 and 14:00 to 17:00 (the break at lunch time is simply left out). 24-hour clock.": "開始-終了の時刻をカンマ区切りで：10-13,14-17 = 10:00〜13:00と14:00〜17:00（昼休みは含めません）。24時間表記。",
    "Length of a meeting": "会議の長さ",
    "30 minutes": "30分",
    "45 minutes": "45分",
    "1 hour 30": "1時間30分",
    "2 hours": "2時間",
    "How far ahead people can book (days)": "何日先まで予約できるか（日数）",
    "Months closed every year": "毎年休みにする月",
    "For example August if the team is away every summer.": "例：チームが毎年夏に不在なら8月。",
    "Closed days (holidays, one-off)": "休業日（祝日・単発）",
    "Who takes appointments and hosts meetings": "誰が予約を受け、会議を主催するか",
    "Who is told when a visitor asks for a meeting, and who may host a room on Meet. Anyone can still be invited to a meeting as a guest.": "訪問者が会議を依頼したときに誰へ通知するか、Meetでルームを主催できるのは誰か。ゲストとしての招待は誰でも可能です。",
    "Team members who take the appointments": "予約を担当するチームメンバー",
    "They are told about each request and can accept or refuse it. Empty = every administrator.": "依頼のたびに通知され、承認または拒否できます。空欄＝全管理者。",
    "Who can host or start a meeting on Meet": "Meetで会議を主催・開始できる人",
    "Every team member": "全チームメンバー",
    "Administrators and managers only": "管理者とマネージャーのみ",
    "Administrators only": "管理者のみ",
    "Managers = a team member whose role is named \"Manager\". Others can still join with the room link as a guest or a team member.": "マネージャー＝役割名が「Manager」のメンバー。それ以外の人もルームのリンクからゲストまたはメンバーとして参加できます。",
    "Also allow these team members to host": "次のメンバーにも主催を許可",
    "Only used when the choice above is not \"Every team member\".": "上の選択が「全チームメンバー」でない場合のみ使用されます。",
    "Uploads: file types and sizes": "アップロード：ファイルの種類とサイズ",
    "What people can upload anywhere in the CRM (tickets, tasks, chat, notes, library, client portal). Pictures are always optimised to WebP. Dangerous types (programs, scripts) stay blocked whatever you write.": "CRM内のどこでもアップロードできるもの（チケット、タスク、チャット、ノート、ライブラリ、顧客ポータル）。画像は常にWebPに最適化されます。危険な種類（プログラム、スクリプト）は何を書いてもブロックされます。",
