    "Tick the days people can book, set the hours of each day (10-13,14-17 = 10:00 to 13:00 and 14:00 to 17:00, 24-hour clock) and choose the team members who take the meetings that day. A visitor is offered a time only when at least one of them is free, and the meeting is given to the one who is free. No one chosen = the team members below.": "予約できる曜日にチェックを入れ、各日の時間（10-13,14-17 = 10:00〜13:00と14:00〜17:00、24時間表記）とその日の会議を担当するメンバーを選びます。担当者の誰かが空いている時間だけが表示され、会議は空いている人に割り当てられます。誰も選ばない場合は下のチームが対象です。",
    "Default team for the meetings": "会議のデフォルトチーム",
    "Used for a day with nobody chosen in the weekly schedule. They are told about each request and can accept or refuse it. Empty = every administrator.": "週間スケジュールで誰も選ばれていない日に使われます。依頼ごとに通知され、承認または拒否できます。空欄＝全管理者。",
