    "Several addresses can be separated by commas. The date becomes the sending time when you send.": "複数のアドレスはカンマで区切れます。送信時に日付は送信時刻になります。",
    "Up to 10 MB per file, 20 MB in all.": "1ファイル10MBまで、合計20MBまで。",
