    "Expand all": "すべて開く",
    "Collapse all": "すべて閉じる",
    "Addresses a lead mail can be sent from, besides hello@trtmaroc.com (always first, the default) and the staff member's own email. Your mail server must allow them. Separate several with commas.": "hello@trtmaroc.com（常に先頭・既定）とスタッフ本人のメールに加えて、リードのメールの送信元にできるアドレス。メールサーバーが許可している必要があります。複数はカンマで区切ります。",
    "Billing and options": "請求とオプション",
    "Replying to": "返信先:",
    "You": "あなた",
    "Voice message": "音声メッセージ",
    "Open in new tab": "新しいタブで開く",
    "Send-from accounts": "送信元アカウント",
    "Some mail servers only accept a sender that is the account used to log in. Give each address you send from (for example hello@trtmaroc.com) its own login here; the CRM uses it when that address is chosen as the sender of a lead mail. Leave the server empty to use the one above.": "メールサーバーによっては、ログインに使うアカウントと同じ送信者しか受け付けません。送信元アドレス（例: hello@trtmaroc.com）ごとに専用のログイン情報をここに入力してください。リードのメールの送信元にそのアドレスが選ばれたとき、CRMはそれを使います。サーバーを空にすると上のサーバーを使います。",
    "Same as the sender email": "送信者メールと同じ",
    "Use another mail server for this address": "このアドレスに別のメールサーバーを使う",
    "No send-from account yet.": "送信元アカウントはまだありません。",
    "Add an account": "アカウントを追加",
    "Save accounts": "アカウントを保存",
    "Send-from accounts saved": "送信元アカウントを保存しました",
    "Save first, then test. The passwords are stored on the server and never shown again.": "先に保存してからテストしてください。パスワードはサーバーに保存され、再表示されません。",
    "See every event, private ones included": "すべてのイベントを表示（非公開を含む）",
    "Edit and delete events of others": "他の人のイベントを編集・削除",
    "Anyone who can open the Calendar adds events": "カレンダーを開ける人は誰でもイベントを追加できます",
    "Everyone edits their own events": "自分のイベントは誰でも編集できます",
    "Everyone deletes their own events": "自分のイベントは誰でも削除できます",
    "Send it automatically at a chosen date and time": "指定した日時に自動で送信する",
    "It is sent at the first run of the automatic tasks after that time, from the address chosen above. Every check must be confirmed first.": "その時刻以降、最初の自動タスク実行時に、上で選んだアドレスから送信されます。先にすべての項目を確認する必要があります。",
    "Scheduled for": "送信予定",
    "Not sent automatically": "自動送信されませんでした",
    "The text changed, so the checks and the schedule were cancelled. Confirm the checks, then schedule it again.": "本文が変更されたため、確認項目と送信予約が取り消されました。項目を確認してから、もう一度予約してください。",
    "Scheduled lead mails": "予約されたリードメール",
    "Sends the lead mail drafts that have a date and time to send automatically (Lead popup → Mails). A draft goes out at the first run after its time, so the automatic tasks must run often (for example every 5 minutes).": "自動送信の日時が設定されたリードのメール下書きを送信します（リードのポップアップ → メール）。下書きは予定時刻後の最初の実行で送信されるため、自動タスクは頻繁に（例: 5分ごと）実行する必要があります。",
    "Send the scheduled lead mails": "予約されたリードメールを送信する",
    "Choose a date and time in the future to send the mail": "送信する日時は未来にしてください",
    "Add the email address to send to before scheduling": "予約する前に送信先のメールアドレスを入力してください",
    "Write a subject before scheduling": "予約する前に件名を入力してください",
    "Confirm every check before scheduling": "予約する前にすべての項目を確認してください",
    "The date to send the mail is not valid": "送信日時が正しくありません",
    "Send automatically": "自動送信",
    "Remind me": "リマインドする",
    "You are told on the bell, by email and on Telegram or WhatsApp (if set in your profile) at the first run of the automatic tasks after that time. Only you see this note.": "その時刻以降の最初の自動タスク実行時に、ベル、メール、Telegram または WhatsApp（プロフィールで設定している場合）でお知らせします。このメモはあなただけに表示されます。",
    "Note and ticket reminders": "メモのリマインダー",
    "A note with \"Remind me at\" tells its owner on the bell, by email and on Telegram / WhatsApp (if set in their profile) at the first run after that time, so the automatic tasks must run often (for example every 5 minutes).": "「リマインドする」を設定したメモは、その時刻以降の最初の実行時に、持ち主へベル、メール、Telegram / WhatsApp（プロフィールで設定している場合）で通知します。自動タスクは頻繁に（例: 5分ごと）実行する必要があります。",
    "Send the note reminders": "メモのリマインダーを送信する",
    "Remind me at": "リマインド日時",
