    "Remind me about this ticket": "このチケットをリマインド",
    "Only you are told: on the bell, by email and on Telegram or WhatsApp (if set in your profile) at the first run of the automatic tasks after that time.": "通知されるのはあなただけです。その時刻以降の最初の自動タスク実行時に、ベル、メール、Telegram または WhatsApp（プロフィールで設定している場合）で届きます。",
