    "When a ticket gets a status, the client receives the message you write here, in the conversation and/or by email. Use the fields to personalise it.": "チケットがあるステータスになると、ここで書いたメッセージが会話内やメールでクライアントに届きます。フィールドで内容を調整できます。",
    "When a request is received (created by the client)": "依頼を受信したとき（クライアントが作成）",
