    "API and webhooks": "APIとWebhook",
    "Two ways to talk to the CRM from outside, both secure: keys to read and push data, webhooks to be told when something happens.": "外部からCRMと通信する安全な2つの方法：データの読み取り・送信用のキーと、出来事を通知するWebhook。",
