    "Webhooks": "Webhook",
    "How to use": "使い方",
    "New API key": "新しいAPIキー",
    "An API key lets another program (a website form, n8n, Zapier, your own code) read or push data. Give each program its own key with only what it needs, and revoke it when it is not used any more.": "APIキーを使うと、他のプログラム（サイトのフォーム、n8n、Zapier、自作コード）がデータを読み取り・送信できます。プログラムごとに必要な権限だけを持つキーを発行し、使わなくなったら無効にしてください。",
