    "A webhook is the other direction: when something happens in the CRM (a lead arrives, a task is created…) the CRM calls the address you give, with the data, signed so that your program can check it really comes from here.": "Webhookは逆方向です。CRMで出来事（リードの到着、タスクの作成など）が起きると、指定したアドレスにデータを送ります。署名付きなので、プログラム側でここから来たことを確認できます。",
