    "Lists take ?limit= (up to 100), ?page=, ?q= (search) and ?updated_since= (ISO date), and answer { data, page, limit, total }.": "一覧は ?limit=（最大100）、?page=、?q=（検索）、?updated_since=（ISO日付）を受け付け、{ data, page, limit, total } を返します。",
