    "Check a webhook call": "Webhook呼び出しを検証",
    "Each call has the headers X-TRT-Event and X-TRT-Signature (t=<seconds>,v1=<hmac>). Recompute the HMAC SHA-256 of \"<t>.<raw body>\" with your signing secret and compare. Refuse calls whose t is older than 5 minutes.": "各呼び出しにはヘッダー X-TRT-Event と X-TRT-Signature（t=<秒>,v1=<hmac>）が付きます。署名シークレットで「<t>.<生の本文>」のHMAC SHA-256を再計算して比較してください。tが5分より古い呼び出しは拒否してください。",
