    "What the app learns about the person: id, name, email, photo, staff id, whether they are an administrator and their role. Any OpenID Connect library works with the discovery address.": "アプリが知ることができる情報:ID、名前、メール、写真、スタッフID、管理者かどうか、役割。ディスカバリーアドレスがあればどのOpenID Connectライブラリでも使えます。",
