    "It goes out at the first run of the automatic tasks after that time (Settings → Cron job), so they must run often, for example every 5 minutes.": "その時刻以降、自動タスクの最初の実行時に送信されます(設定 → Cron job)。そのため、5分ごとなど頻繁に実行する必要があります。",
