    "Appointment request: waiting for you": "予約リクエスト:対応待ち",
    "Nobody is invited and no reminder goes out until you accept. The person who asked is told by email.": "承認するまで誰も招待されず、リマインダーも送信されません。依頼した人にはメールで通知されます。",
    "Send an appointment request to the calendar": "カレンダーに予約リクエストを送る",
    "The key needs the scope “Send appointment requests”. The request is a draft on the calendar (⏳): nobody is invited and no reminder goes out until a team member accepts it. The same room is never recorded twice. Ask its state with GET /calendar/events/<id>, or subscribe to the webhooks appointment.accepted and appointment.declined.": "キーには「予約リクエストを送る」スコープが必要です。リクエストはカレンダー上の下書き(⏳)で、チームメンバーが承認するまで誰も招待されず、リマインダーも送信されません。同じルームが2回記録されることはありません。状態は GET /calendar/events/<id> で確認するか、Webhook の appointment.accepted と appointment.declined を購読してください。",
    "confirmation sent": "確認を送信しました",
