    "@ mentions a colleague, # adds a tag, and you can paste or drop screenshots.": "@ で同僚にメンション、# でタグを追加、スクリーンショットは貼り付けやドロップができます。",
    "Also email it to the client (with the screenshots)": "クライアントにもメールで送る(スクリーンショット付き)",
