    "Every certificate, language exam or course you pass gives points and can win a trophy with a cash prize between 200 and 1000 MAD, on top of the prime of the goal. Pick a goal in the Catalog and ask for approval: the first step is the easiest.": "資格、語学試験、講座に合格するごとにポイントがもらえ、目標のボーナスに加えて200〜1000 MADの賞金付きトロフィーを獲得できます。カタログから目標を選んで承認を依頼しましょう。最初の一歩がいちばん簡単です。",
