    "Also remind the client, the lead and the guests by email": "クライアント、リード、ゲストにもメールでリマインドする",
    "Choose a client or a lead, or add a guest email, to switch this on.": "オンにするには、クライアントまたはリードを選ぶか、ゲストのメールを追加してください。",
